import sys
input = sys.stdin.readline
for _ in range(int(input())):
	(n, m) = map(int, input().split())
	T = {}
	A = []
	for _ in range(n):
		I = list(map(int, input().split()))
		J = [0] * (m + 1)
		for i in range(m):
			J[I[i]] = i + 1
		D = T
		for num in J[1:]:
			if not num in D:
				D[num] = {}
			D = D[num]
		A.append(I)
	Ans2 = []
	for data in A:
		Ans = 0
		D = T
		for num in data:
			if num in D:
				Ans += 1
				D = D[num]
			else:
				break
		Ans2.append(Ans)
	print(*Ans2)
